/*
 * cold/cold.h - COLD_START, the SAU2 image's cold-start code
 *
 * Generated by: Claude Opus 5.5
 *
 * The code is hand-written assembly, cold/sau2/cold_start.s (bead
 * source-gfn1; analysis in docs/rfc-cold-start.md).  The map:
 *
 *   D22  101400  COLD               loaded at 101400, size = 7FC
 *        101400  COLD
 *        101420  MOVE_TO_PPN
 *
 * COLD runs once, from the boot loader, with the MMU off; nothing in the
 * kernel calls it.  What C may need are the shapes of its records:
 * OS_$INIT (os/os.h) receives &cold_boot_params and &cold_diskless_info,
 * and the map table format is what step 3 of epic source-nqcs generates.
 * The addresses below are the image's low (physical) addresses.
 */

#ifndef COLD_COLD_H
#define COLD_COLD_H

#include "base/base.h"

/* The RFC header and info block at the start of the image file. */
#define COLD_RFC_LOAD_ADDR      0x00101400u /* header +0: file byte 0 */
#define COLD_RFC_START_ADDR     0x00101424u /* header +4: cold_start_entry */
#define COLD_RFC_MACHINE_SAU2   2           /* header +8: a WORD, then a zero word */
#define COLD_INFO_MAGIC         0xFEED2B03u /* info +0xC */
#define COLD_SPLIT_PPN          0x55Fu      /* info +0x10: pages from here are loaded at MOVE_TO_PPN */
#define COLD_SIZE               0x7FCu      /* map: COLD size = 7FC; COLD + 0x7FC is the initial SP */

/* COLD: the first byte of the segment (the RFC header). */
extern uint8_t COLD[COLD_SIZE];

/* MOVE_TO_PPN (0x101420): the physical page the pages past the split go to (0x600). */
extern uint32_t MOVE_TO_PPN;

/*
 * cold_start_entry (0x101424): the RFC start address.  Not a C function:
 * it takes its arguments off the loader's stack (return address, two
 * boot_params longwords, the diskless block pointer) and ends in OS_$INIT.
 */
extern void cold_start_entry(void);

/*
 * One entry of the MMU map tables (0x101850 cold_map_table, 0x10181C
 * cold_ident_map_table), 10 bytes, big-endian, 2-byte aligned: count.w (0
 * ends the table), ppn.w, flags | va.l, prot.w.  Flag bits of va: 31 =
 * kernel page (MMAP wire_count 0x80), 30 = COLD's pages (0x40), 29 = not
 * global (PFT bit 12 clear).  prot is the high word of the PFT entry.
 */
typedef struct cold_map_entry_t {
    uint16_t count;     /* +0 pages; 0 ends the table */
    uint16_t ppn;       /* +2 first physical page */
    uint32_t va;        /* +4 flags (bits 31..29) | first VA */
    uint16_t prot;      /* +8 PFT entry bits 31..16 */
} __attribute__((packed, aligned(2))) cold_map_entry_t;

_Static_assert(sizeof(cold_map_entry_t) == 10, "cold map table entry: 10 bytes");
_Static_assert(__builtin_offsetof(cold_map_entry_t, va) == 4, "cold_map_entry_t.va");
_Static_assert(__builtin_offsetof(cold_map_entry_t, prot) == 8, "cold_map_entry_t.prot");

#define COLD_MAP_WIRED          0x80000000u
#define COLD_MAP_COLD           0x40000000u
#define COLD_MAP_PRIVATE        0x20000000u

/* 0x101850: 17 entries and the terminating zero count (0x1018FA). */
#define COLD_MAP_TABLE_ENTRIES  17
extern cold_map_entry_t cold_map_table[COLD_MAP_TABLE_ENTRIES];

/*
 * The two records OS_$INIT receives (cold_enter_kernel, 0x1016F8):
 * cold_boot_params, 9 longwords at 0x1018FC (longwords 0 and 1 are the
 * entry's d1/d2: device.w, ctlr.w, unit.w, flags.w; flags bit 15 = trap
 * to the debugger first), and cold_diskless_info, 12 longwords at
 * 0x101908 (the 7 longwords of the diskless block on a device 2 or 6
 * boot, then COLD's saved SP, MMAP's physical address and the MMU
 * geometry words).  The two overlap: the boot record's last six
 * longwords are the diskless record's first six.
 */
#define COLD_BOOT_PARAMS_LONGS   9
#define COLD_DISKLESS_INFO_LONGS 12
extern uint32_t cold_boot_params[COLD_BOOT_PARAMS_LONGS];
extern uint32_t cold_diskless_info[COLD_DISKLESS_INFO_LONGS];

#endif /* COLD_COLD_H */
